"grammar": [
{"pattern":"～てから","usage":"sau khi làm gì rồi mới...","example":"野菜を洗ってから、小さく切ります。","example_reading":"やさいをあらってから、ちいさくきります。","example_meaning":"Sau khi rửa rau xong tôi mới cắt nhỏ."},
{"pattern":"～ておく","usage":"làm trước và để nguyên như vậy","example":"肉は前日から味付けしておくと、もっと美味しくなります。","example_reading":"にくはぜんじつからあじつけしておくと、もっとおいしくなります。","example_meaning":"Nếu ướp thịt từ hôm trước thì sẽ ngon hơn."},
{"pattern":"～たら","usage":"nếu...thì, khi...thì","example":"スープが冷めたら、もう一度温めてください。","example_reading":"すーぷがさめたら、もういちどあたためてください。","example_meaning":"Nếu súp nguội thì hãy hâm nóng lại một lần nữa."},
{"pattern":"～すぎる","usage":"quá mức","example":"塩を入れすぎると、料理がしょっぱくなってしまいます。","example_reading":"しおをいれすぎると、りょうりがしょっぱくなってしまいます。","example_meaning":"Nếu cho quá nhiều muối thì món ăn sẽ bị mặn."},
{"pattern":"～ように","usage":"sao cho, để cho","example":"焦げないように、弱火でじっくり焼いてください。","example_reading":"こげないように、よわびでじっくりやいてください。","example_meaning":"Hãy nướng kỹ với lửa nhỏ sao cho không bị cháy."},
{"pattern":"～か～ないかのうちに","usage":"ngay khi vừa mới...","example":"肉を焼き終わるか終わらないかのうちに、すぐに皿に盛りました。","example_reading":"にくをやきおわるかおわらないかのうちに、すぐにさらにもりました。","example_meaning":"Ngay khi vừa nướng xong thịt, tôi liền bày ra đĩa."},
{"pattern":"～一方だ","usage":"chỉ có ngày càng...(xu hướng một chiều)","example":"外食が増える一方で、自炊する時間は減る一方です。","example_reading":"がいしょくがふえるいっぽうで、じすいするじかんはへるいっぽうです。","example_meaning":"Trong khi ăn ngoài ngày càng tăng thì thời gian tự nấu ăn cứ ngày càng giảm."},
{"pattern":"～ばかりだ","usage":"vừa mới làm xong","example":"このケーキは焼き上がったばかりなので、まだ熱いです。","example_reading":"このけーきはやきあがったばかりなので、まだあついです。","example_meaning":"Vì chiếc bánh này vừa mới nướng xong nên vẫn còn nóng."},
{"pattern":"～ながら","usage":"vừa...vừa...","example":"味を見ながら調整します。","example_reading":"あじをみながらちょうせいします。","example_meaning":"Tôi vừa nếm vừa điều chỉnh."},
{"pattern":"～たまま","usage":"để nguyên trạng thái","example":"ふたを閉めたまま蒸します。","example_reading":"ふたをしめたままむします。","example_meaning":"Hấp với nắp đậy nguyên."},
{"pattern":"～ないように","usage":"để không bị...","example":"焦げないように火を弱めます。","example_reading":"こげないようにひをよわめます。","example_meaning":"Hạ lửa để không bị cháy."},
{"pattern":"～てはどうですか","usage":"hay là làm...?","example":"少し塩を足してはどうですか。","example_reading":"すこししおをたしてはどうですか。","example_meaning":"Hay là thêm chút muối?"},
{"pattern":"～ような気がする","usage":"có cảm giác như","example":"少し薄いような気がします。","example_reading":"すこしうすいようなきがします。","example_meaning":"Tôi có cảm giác hơi nhạt."},
{"pattern":"～たて","usage":"vừa mới xong","example":"焼きたてのパンはおいしいです。","example_reading":"やきたてのぱんはおいしいです。","example_meaning":"Bánh mì vừa ra lò rất ngon."},
{"pattern":"～かけ","usage":"đang dở dang","example":"食べかけのまま置かないでください。","example_reading":"たべかけのままおかないでください。","example_meaning":"Đừng để đồ ăn dở dang như thế."},
{"pattern":"～っぱなし","usage":"để mặc nguyên","example":"火をつけっぱなしにしないでください。","example_reading":"ひをつけっぱなしにしないでください。","example_meaning":"Đừng để lửa cháy mãi như vậy."},
{"pattern":"～ほど","usage":"đến mức","example":"食べきれないほど作りました。","example_reading":"たべきれないほどつくりました。","example_meaning":"Tôi nấu nhiều đến mức ăn không hết."},
{"pattern":"～きれない","usage":"không thể...hết","example":"一人では食べきれません。","example_reading":"ひとりではたべきれません。","example_meaning":"Một mình tôi ăn không hết."},
{"pattern":"～に比べると","usage":"nếu so với","example":"外食に比べると自炊は安いです。","example_reading":"がいしょくにくらべるとじすいはやすいです。","example_meaning":"So với ăn ngoài thì tự nấu rẻ hơn."},
{"pattern":"～たものだ","usage":"ngày xưa thường hay","example":"子どもの頃よく作ったものです。","example_reading":"こどものころよくつくったものです。","example_meaning":"Hồi nhỏ tôi hay làm món này lắm."}
]
